def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 10:
        return 'C'

    opp_def = 0
    our_def = 0
    for me, opp in history:
        if opp == 'D':
            opp_def += 1
        if me == 'D':
            our_def += 1

    our_coop = n - our_def
    our_coop_rate = our_coop / n
    opp_def_rate = opp_def / n

    # Check for a strict retaliator (e.g., Tit-for-Tat) that retaliates to a single defection.
    strict = False
    consec_our_def = 0
    for me, opp in history:
        if me == 'D':
            consec_our_def += 1
        else:
            consec_our_def = 0
        if me == 'D' and opp == 'D' and consec_our_def <= 2:
            strict = True
            break

    if strict:
        if n == 99:
            return 'D'
        return 'C'

    if opp_def == 0:
        return 'D'

    if opp_def_rate > 0.6:
        return 'D'

    last_me, last_opp = history[-1]

    if last_opp == 'D':
        if last_me == 'C':
            return 'D'
        else:
            if opp_def_rate > 0.3:
                return 'D'
            else:
                return 'C'
    else:
        if last_me == 'D':
            if our_coop_rate > 0.7 and opp_def_rate < 0.3:
                return 'D'
            else:
                return 'C'
        else:
            if our_coop_rate > 0.75 and opp_def_rate < 0.2:
                return 'D'
            else:
                return 'C'
